// Image helper: maps a /images/*.jpg path to its build-time WebP twin
// (generated by scripts/optimize-images.mjs) plus width/height for CLS.
// Falls back to the original JPG when no WebP/dims entry exists (e.g. a
// brand-new article image whose WebP has not been generated yet).
import dims from '../data/image-dims.json';

type Dims = { webp: string; w: number; h: number };
const map = dims as unknown as Record<string, Dims>;

export function imgProps(src: string): { src: string; width?: number; height?: number } {
  const d = map[src];
  if (!d) return { src };
  return { src: d.webp, width: d.w, height: d.h };
}
